  from jsonb_to_recordset($j$[{"topic":"math","band":"c11-12","difficulty":2,"q":"f(x) = ৪x³ হলে x = ৪ বিন্দুতে f′(x) এর মান কত?","options":["২৫৬","১৯২","৭৬৮","১২৮"],"answer_idx":1,"explanation":"f′(x) = ১২x²। x = ৪ বসালে ১৯২।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":3,"q":"∫₀১ ২x¹ dx এর মান কত?","options":["৩","২","৪","১"],"answer_idx":3,"explanation":"∫ ২x¹ dx = ২x²/২। ০ থেকে ১ সীমায় = ১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":2,"q":"৯C৩ এর মান কত?","options":["৭৫","৮৪","৯৩","৫০৪"],"answer_idx":1,"explanation":"nCr = n!/{r!(n−r)!} = ৮৪।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":2,"q":"|৪ ১; ১ ৬| (২×২ নির্ণায়ক, প্রথম সারি ৪, ১ ও দ্বিতীয় সারি ১, ৬) এর মান কত?","options":["−২","২৩","−২৩","২৫"],"answer_idx":1,"explanation":"নির্ণায়ক = ad − bc = ৪ × ৬ − ১ × ১ = ২৩।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":3,"q":"i৬৩ এর মান কত? (i = √−১)","options":["−i","১","i","−১"],"answer_idx":0,"explanation":"i-এর ঘাত চার চার করে ঘোরে: i⁴ = ১। ৬৩ ÷ ৪ এর ভাগশেষ ৩, তাই i৬৩ = −i।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":1,"q":"log৫ ২৫ = কত?","options":["২","১","৫","৩"],"answer_idx":0,"explanation":"৫² = ২৫, তাই log৫ ২৫ = ২।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":2,"q":"২x² − ৬x + ১ = ০ সমীকরণের নিরূপক (ডিসক্রিমিন্যান্ট) এর মান কত?","options":["৪৪","−২৮","২৮","৩২"],"answer_idx":2,"explanation":"নিরূপক = b² − ৪ac = ৩৬ − ৮ = ২৮।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c11-12","difficulty":1,"q":"(−১, ৩) ও (৩, ১৫) বিন্দুগামী সরলরেখার ঢাল কত?","options":["−৩","৪","৩","২"],"answer_